src = src.replace('requestAnimationFrame(frame);\n})();', 'globalThis.__t = { get balls(){return balls}, step };\n})();');
const el = () => ({ value: '', textContent: '', addEventListener(){}, getBoundingClientRect: () => ({ width: 900, height: 480, left: 0, top: 0 }), getContext: () => new Proxy({}, { get: () => () => ({ addColorStop(){} }) }) });
const els = { gravity: { ...el(), value: '1400' }, bounce: { ...el(), value: '0.85' } };
globalThis.document = { getElementById: id => els[id] ||= el(), documentElement: {} };
globalThis.window = { devicePixelRatio: 1, addEventListener(){} };
globalThis.getComputedStyle = () => ({ getPropertyValue: () => '#ccc' });
globalThis.performance = { now: () => 0 };
globalThis.requestAnimationFrame = () => {};
eval(src);
const { step } = __t;
for (let i = 0; i < 60 * 4 * 5; i++) step(1 / 240);
let ok = true;
for (const b of __t.balls) {
  if (b.x < b.r - 0.5 || b.x > 900 - b.r + 0.5 || b.y > 480 - b.r + 0.5 || !isFinite(b.x + b.y)) ok = false;
}
const bs = __t.balls; let maxOverlap = 0;
for (let i = 0; i < bs.length; i++) for (let j = i + 1; j < bs.length; j++) maxOverlap = Math.max(maxOverlap, bs[i].r + bs[j].r - Math.hypot(bs[i].x - bs[j].x, bs[i].y - bs[j].y));
console.log({ balls: bs.length, inBounds: ok, maxOverlap: maxOverlap.toFixed(2), sample: bs.slice(0, 3).map(b => [b.x.toFixed(0), b.y.toFixed(0), b.vy.toFixed(0)]) });
EOF
